import{_ as e,c as t,o as a,N as s,aH as i}from"./chunks/framework.l15gEyFz.js";const b=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","order":-1,"outline":[0,4]},"headers":[],"relativePath":"products/ultra-web-wallet/index.md","filePath":"products/ultra-web-wallet/index.md","lastUpdated":null}'),n={name:"products/ultra-web-wallet/index.md"},l=s('<h1 id="ultra-web-wallet" tabindex="-1">Ultra Web Wallet <a class="header-anchor" href="#ultra-web-wallet" aria-label="Permalink to &quot;Ultra Web Wallet&quot;">​</a></h1><p><img src="'+i+`" alt=""></p><p>The <strong>Ultra Web Wallet</strong> is a browser-based, non-custodial wallet for Easy Blockchain Account (EBA) users. It opens in a popup when a dApp uses <code>@ultraos/wallet-sdk</code>, so users can connect and approve signing requests without installing a browser extension.</p><p>The SDK presents the same top-level API for the Web Wallet and the Ultra Wallet Browser Extension. By default, it uses the extension when one is detected and falls back to the Web Wallet otherwise. A dApp can also explicitly request the Web Wallet provider.</p><h2 id="current-capabilities" tabindex="-1">Current capabilities <a class="header-anchor" href="#current-capabilities" aria-label="Permalink to &quot;Current capabilities&quot;">​</a></h2><p>The Web Wallet currently supports:</p><ul><li>Connecting and disconnecting a dApp.</li><li>Signing messages.</li><li>Signing one or more transaction actions. Transactions are broadcast by default; the <code>signOnly</code> option returns the signed transaction without broadcasting it.</li><li>Returning the configured Ultra network&#39;s chain ID.</li></ul><p>The Web Wallet currently supports EBA accounts only. Persistent wallet events, runtime network switching, network management, and the extension&#39;s broader account-query APIs are not supported by the popup transport.</p><h2 id="integrating-the-web-wallet" tabindex="-1">Integrating the Web Wallet <a class="header-anchor" href="#integrating-the-web-wallet" aria-label="Permalink to &quot;Integrating the Web Wallet&quot;">​</a></h2><p>Install and initialize the <a href="./../ultra-wallet-sdk/">Ultra Wallet SDK</a>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { UltraWalletSDK } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ultraos/wallet-sdk&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> wallet</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> UltraWalletSDK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    environment: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mainnet&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>This configuration automatically uses the extension when available. To always use the Web Wallet, set <code>provider: &#39;web&#39;</code>.</p><p>Calls that open the wallet, such as <code>connect()</code>, <code>signMessage()</code>, and <code>signTransaction()</code>, should be made directly from a user action such as a button click. Browsers may block popups created outside a user gesture.</p><div class="info custom-block"><p class="custom-block-title">Key storage</p><p>The private key is generated and retained in an encrypted vault in the Web Wallet&#39;s browser storage. The encryption key is assembled during authentication from a device-local part and a part returned by Ultra&#39;s device service; Ultra does not store the complete private key.</p></div>`,14),r=[l];function o(p,c,h,d,u,k){return a(),t("div",null,r)}const w=e(n,[["render",o]]);export{b as __pageData,w as default};
